import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as a,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Cursor Rules 实践","description":"项目级 AI 行为规范案例：.mdc 格式与四种 Rule Type、规则内容结构、实操场景与渐进完善的最佳实践。","frontmatter":{"title":"Cursor Rules 实践","description":"项目级 AI 行为规范案例：.mdc 格式与四种 Rule Type、规则内容结构、实操场景与渐进完善的最佳实践。","domain":"tech","tags":["tech","ai-coding","case","cursor","rules"],"navOrder":95,"topicId":"ai-coding-cursor-rules","layer":"appendix","status":"case","nodeType":"evidence","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/ai-coding/cursor-rules.md","filePath":"zh/tech/appendices/ai-coding/cursor-rules.md","lastUpdated":1791166440000}'),o={name:"zh/tech/appendices/ai-coding/cursor-rules.md"};function n(l,e,d,i,c,p){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="cursor-rules-实践" tabindex="-1">Cursor Rules 实践 <a class="header-anchor" href="#cursor-rules-实践" aria-label="Permalink to &quot;Cursor Rules 实践&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://juejin.cn/post/7484787785887989798" target="_blank" rel="noreferrer">新版 Cursor Rules .mdc 格式文件使用经验</a> ｜ <a href="https://docs.cursor.com/features/rules" target="_blank" rel="noreferrer">Cursor 官方文档</a></p></blockquote><h2 id="什么是-cursor-rules" tabindex="-1">什么是 Cursor Rules <a class="header-anchor" href="#什么是-cursor-rules" aria-label="Permalink to &quot;什么是 Cursor Rules&quot;">​</a></h2><p>放在项目根目录的<strong>项目级 AI 行为规范配置文件</strong>，为项目定制 AI 行为（强制代码风格、禁止特定 API 等）。可以理解为一份给 AI 阅读的<strong>项目说明书</strong>：把「衣服要叠好放衣柜」这类要求写成整理指南，AI 每次来都能按指南操作，不用重复交代。</p><table tabindex="0"><thead><tr><th>版本</th><th>说明</th></tr></thead><tbody><tr><td><code>.cursorrules</code></td><td>旧版单一文件（接近废弃）</td></tr><tr><td><code>.cursor/rules/*.mdc</code></td><td>新版 Project Rules，多文件分类管理</td></tr></tbody></table><blockquote><p>迁移期建议保留旧文件，团队成员未全部升级到 0.46+ 前不删 <code>.cursorrules</code>。</p></blockquote><p>通用化的「规则即上下文资产」视角见主线<a href="/zh/tech/03-context/context-engineering.html">上下文工程</a>；与 Claude 系的 AGENTS.md、Skills 的对照见 <a href="/zh/tech/06-agent-systems/skills.html">Agent Skills</a>。</p><h2 id="rule-type-四种生效规则" tabindex="-1">Rule Type（四种生效规则） <a class="header-anchor" href="#rule-type-四种生效规则" aria-label="Permalink to &quot;Rule Type（四种生效规则）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>生效规则</th></tr></thead><tbody><tr><td><strong>Always</strong></td><td>始终生效，包括 <code>cmd + K</code> 对话</td></tr><tr><td><strong>Auto Attached</strong></td><td>匹配特定文件时生效（正则匹配路径，如 <code>*tsx</code>、<code>src/config/*</code>）</td></tr><tr><td><strong>Agent Request</strong></td><td>代理模式下可见，代理决定是否查看完整规则</td></tr><tr><td><strong>Manual</strong></td><td>对话中手动 <code>@</code> 才生效</td></tr></tbody></table><h2 id="规则内容结构" tabindex="-1">规则内容结构 <a class="header-anchor" href="#规则内容结构" aria-label="Permalink to &quot;规则内容结构&quot;">​</a></h2><p>一份优质规则通常包含：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 角色        → 你是谁（Python 开发专家，特长 Flask）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 目标        → 要干什么（高效 API、易维护、可扩展）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 开发规范    → 项目的规矩（类型提示、封装的 request 函数）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 目录结构    → src/components、hooks、utils、api 各归其位</span></span></code></pre></div><h2 id="实操场景" tabindex="-1">实操场景 <a class="header-anchor" href="#实操场景" aria-label="Permalink to &quot;实操场景&quot;">​</a></h2><p><strong>统一包管理器</strong>（AI 总默认 npm，项目用 pnpm）：「安装依赖用 <code>pnpm install</code>，添加包用 <code>pnpm add</code>」。</p><p><strong>强制代码风格</strong>：ESLint Standard、函数式组件、TS 泛型优先于 any。</p><p><strong>架构约定</strong>：API 走 <code>/api</code> 代理、组件按功能模块划分、状态管理 Zustand 避免 Redux 过度设计。</p><p>配置方式：Settings → Rules → Add new rule（自动创建 <code>.mdc</code>）；或 <code>/Generate Cursor Rules</code> 生成初稿再调整；<a href="https://cursor.directory/generate" target="_blank" rel="noreferrer">Cursor Directory</a> 可从旧 <code>.cursorrules</code> + <code>package.json</code> 生成 MDC 初稿（需再调整）。</p><p>目录示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.cursor/rules/</span></span>
<span class="line"><span>  project-overview.mdc   # Always</span></span>
<span class="line"><span>  frontend-style.mdc     # Auto Attached: *tsx, *jsx</span></span>
<span class="line"><span>  backend-rules.mdc      # Auto Attached: *py, *go</span></span>
<span class="line"><span>  testing-rules.mdc      # Auto Attached: *test.*, *spec.*</span></span>
<span class="line"><span>  security-rules.mdc     # Always</span></span></code></pre></div><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ol><li><strong>渐进完善</strong>：从通用规则起步 → 按团队实际习惯自定义 → 每当发现 AI「忘记」某要求就加入规则。没有一蹴而就的完美规则。</li><li><strong>避免规则过多</strong>：规则太多导致上下文膨胀、难以维护。只添加「日常总需要强调，但 AI 因上下文丢失或新会话总忘记」的问题。</li><li><strong>规则分层</strong>：User Rules（本机，如「始终用中文回复」）vs Project Rules（入库共享）。</li><li><strong>写法纪律</strong>（承接 <a href="./cursor-ide-architecture.html">Cursor IDE 架构</a> 的提示设计要点）：不贴身份、少负面约束、名称高辨识度、百科体正文。</li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Cursor Rules = 项目的 AI 说明书：Rule Type 决定生效时机，渐进完善优于一次到位，适度原则防止规则过载，Project Rules 让团队共享统一规范。</p>`,23)])])}const m=t(o,[["render",n]]);export{b as __pageData,m as default};
